pragma solidity >=0.8.0 <0.9.0;

/// @title FighterOps library for managing fighters in the AI Arena game.
/// @author ArenaX Labs Inc.
/// @notice This library is used for creating and managing Fighter NFTs in the AI Arena game.
library FighterOps {

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Emitted when a new Fighter NFT is created.
    event FighterCreated(
        uint256 id,
        uint256 weight,
        uint256 element,
        uint8 generation
    );

    /*//////////////////////////////////////////////////////////////
                                STRUCTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Struct that defines a Fighter's physical attributes.
    struct FighterPhysicalAttributes {
        uint256 head;
        uint256 eyes;
        uint256 mouth;
        uint256 body;
        uint256 hands;
        uint256 feet;
    }

    /// @notice Struct that defines a Fighter NFT.
    struct Fighter {
        uint256 weight;
        uint256 element;
        FighterPhysicalAttributes physicalAttributes;
        uint256 id;
        string modelHash;
        string modelType;
        uint8 generation;
        uint8 iconsType;
        bool dendroidBool;
    }

    /*//////////////////////////////////////////////////////////////
                            PUBLIC FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @notice Emits a FighterCreated event.
    function fighterCreatedEmitter(
        uint256 id,
        uint256 weight,
        uint256 element,
        uint8 generation
    ) 
        public 
    {
        emit FighterCreated(id, weight, element, generation);
    }

    /// @notice Extracting the fighter attributes from the struct
    /// @param self Fighter struct
    /// @return Array of Fighter Attributes 
    function getFighterAttributes(Fighter storage self) public view returns (uint256[6] memory) {
        return [
            self.physicalAttributes.head,
            self.physicalAttributes.eyes,
            self.physicalAttributes.mouth,
            self.physicalAttributes.body,
            self.physicalAttributes.hands,
            self.physicalAttributes.feet
        ];
    }

    /// @notice Gets all of the relevant fighter information 
    function viewFighterInfo(
        Fighter storage self, 
        address owner
    ) 
        public 
        view 
        returns (
            address,
            uint256[6] memory,
            uint256,
            uint256,
            string memory,
            string memory,
            uint16
        )
    {
        return (
            owner,
            getFighterAttributes(self),
            self.weight,
            self.element,
            self.modelHash,
            self.modelType,
            self.generation
        );
    }
}"},"src/FixedPointMathLib.sol":{"content":"// SPDX-License-Identifier: AGPL-3.0-only
pragma solidity >=0.8.0;

/// @notice Arithmetic library with operations for fixed-point numbers.
/// @author Solmate (https://github.com/transmissions11/solmate/blob/main/src/utils/FixedPointMathLib.sol)
/// @author Inspired by USM (https://github.com/usmfum/USM/blob/master/contracts/WadMath.sol)
library FixedPointMathLib {
    /*//////////////////////////////////////////////////////////////
                    SIMPLIFIED FIXED POINT OPERATIONS
    //////////////////////////////////////////////////////////////*/

    uint256 internal constant WAD = 1e18; // The scalar of ETH and most ERC20s.

    function mulWadDown(uint256 x, uint256 y) internal pure returns (uint256) {
        return mulDivDown(x, y, WAD); // Equivalent to (x * y) / WAD rounded down.
    }

    function mulWadUp(uint256 x, uint256 y) internal pure returns (uint256) {
        return mulDivUp(x, y, WAD); // Equivalent to (x * y) / WAD rounded up.
    }

    function divWadDown(uint256 x, uint256 y) internal pure returns (uint256) {
        return mulDivDown(x, WAD, y); // Equivalent to (x * WAD) / y rounded down.
    }

    function divWadUp(uint256 x, uint256 y) internal pure returns (uint256) {
        return mulDivUp(x, WAD, y); // Equivalent to (x * WAD) / y rounded up.
    }

    /*//////////////////////////////////////////////////////////////
                    LOW LEVEL FIXED POINT OPERATIONS
    //////////////////////////////////////////////////////////////*/

    function mulDivDown(
        uint256 x,
        uint256 y,
        uint256 denominator
    ) internal pure returns (uint256 z) {
        assembly {
            // Store x * y in z for now.
            z := mul(x, y)

            // Equivalent to require(denominator != 0 && (x == 0 || (x * y) / x == y))
            if iszero(and(iszero(iszero(denominator)), or(iszero(x), eq(div(z, x), y)))) {
                revert(0, 0)
            }

            // Divide z by the denominator.
            z := div(z, denominator)
        }
    }

    function mulDivUp(
        uint256 x,
        uint256 y,
        uint256 denominator
    ) internal pure returns (uint256 z) {
        assembly {
            // Store x * y in z for now.
            z := mul(x, y)

            // Equivalent to require(denominator != 0 && (x == 0 || (x * y) / x == y))
            if iszero(and(iszero(iszero(denominator)), or(iszero(x), eq(div(z, x), y)))) {
                revert(0, 0)
            }

            // First, divide z - 1 by the denominator and add 1.
            // We allow z - 1 to underflow if z is 0, because we multiply the
            // end result by 0 if z is zero, ensuring we return 0 if z is zero.
            z := mul(iszero(iszero(z)), add(div(sub(z, 1), denominator), 1))
        }
    }

    function rpow(
        uint256 x,
        uint256 n,
        uint256 scalar
    ) internal pure returns (uint256 z) {
        assembly {
            switch x
            case 0 {
                switch n
                case 0 {
                    // 0 ** 0 = 1
                    z := scalar
                }
                default {
                    // 0 ** n = 0
                    z := 0
                }
            }
            default {
                switch mod(n, 2)
                case 0 {
                    // If n is even, store scalar in z for now.
                    z := scalar
                }
                default {
                    // If n is odd, store x in z for now.
                    z := x
                }

                // Shifting right by 1 is like dividing by 2.
                let half := shr(1, scalar)

                for {
                    // Shift n right by 1 before looping to halve it.
                    n := shr(1, n)
                } n {
                    // Shift n right by 1 each iteration to halve it.
                    n := shr(1, n)
                } {
                    // Revert immediately if x ** 2 would overflow.
                    // Equivalent to iszero(eq(div(xx, x), x)) here.
                    if shr(128, x) {
                        revert(0, 0)
                    }

                    // Store x squared.
                    let xx := mul(x, x)

                    // Round to the nearest number.
                    let xxRound := add(xx, half)

                    // Revert if xx + half overflowed.
                    if lt(xxRound, xx) {
                        revert(0, 0)
                    }

                    // Set x to scaled xxRound.
                    x := div(xxRound, scalar)

                    // If n is even:
                    if mod(n, 2) {
                        // Compute z * x.
                        let zx := mul(z, x)

                        // If z * x overflowed:
                        if iszero(eq(div(zx, x), z)) {
                            // Revert if x is non-zero.
                            if iszero(iszero(x)) {
                                revert(0, 0)
                            }
                        }

                        // Round to the nearest number.
                        let zxRound := add(zx, half)

                        // Revert if zx + half overflowed.
                        if lt(zxRound, zx) {
                            revert(0, 0)
                        }

                        // Return properly scaled zxRound.
                        z := div(zxRound, scalar)
                    }
                }
            }
        }
    }

    /*//////////////////////////////////////////////////////////////
                        GENERAL NUMBER UTILITIES
    //////////////////////////////////////////////////////////////*/

    function sqrt(uint256 x) internal pure returns (uint256 z) {
        assembly {
            // Start off with z at 1.
            z := 1

            // Used below to help find a nearby power of 2.
            let y := x

            // Find the lowest power of 2 that is at least sqrt(x).
            if iszero(lt(y, 0x100000000000000000000000000000000)) {
                y := shr(128, y) // Like dividing by 2 ** 128.
                z := shl(64, z) // Like multiplying by 2 ** 64.
            }
            if iszero(lt(y, 0x10000000000000000)) {
                y := shr(64, y) // Like dividing by 2 ** 64.
                z := shl(32, z) // Like multiplying by 2 ** 32.
            }
            if iszero(lt(y, 0x100000000)) {
                y := shr(32, y) // Like dividing by 2 ** 32.
                z := shl(16, z) // Like multiplying by 2 ** 16.
            }
            if iszero(lt(y, 0x10000)) {
                y := shr(16, y) // Like dividing by 2 ** 16.
                z := shl(8, z) // Like multiplying by 2 ** 8.
            }
            if iszero(lt(y, 0x100)) {
                y := shr(8, y) // Like dividing by 2 ** 8.
                z := shl(4, z) // Like multiplying by 2 ** 4.
            }
            if iszero(lt(y, 0x10)) {
                y := shr(4, y) // Like dividing by 2 ** 4.
                z := shl(2, z) // Like multiplying by 2 ** 2.
            }
            if iszero(lt(y, 0x8)) {
                // Equivalent to 2 ** z.
                z := shl(1, z)
            }

            // Shifting right by 1 is like dividing by 2.
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))
            z := shr(1, add(z, div(x, z)))

            // Compute a rounded down version of z.
            let zRoundDown := div(x, z)

            // If zRoundDown is smaller, use it.
            if lt(zRoundDown, z) {
                z := zRoundDown
            }
        }
    }
}"},"src/GameItems.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;

import { Neuron } from "./Neuron.sol";
import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";

/// @title GameItems
/// @author ArenaX Labs Inc.
/// @notice This contract represents a collection of game items used in AI Arena.
contract GameItems is ERC1155 {

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Event emitted when a game item is bought.
    /// @param buyer The address of the buyer.
    /// @param tokenId The id of the game item.
    /// @param quantity The quantity of the game item.
    event BoughtItem(address buyer, uint256 tokenId, uint256 quantity);

    /// @notice Event emitted when an item is locked and thus cannot be traded.
    /// @param tokenId The id of the game item.
    event Locked(uint256 tokenId);

    /// @notice Event emitted when an item is unlocked and can be traded.
    /// @param tokenId The id of the game item.
    event Unlocked(uint256 tokenId);

    /*//////////////////////////////////////////////////////////////
                                STRUCTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Struct for game item attributes
    struct GameItemAttributes {
        string name;
        bool finiteSupply;
        bool transferable;
        uint256 itemsRemaining;
        uint256 itemPrice;
        uint256 dailyAllowance;
    }  

    /*//////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    /// @notice The name of this smart contract.
    string public name = "AI Arena Game Items";

    /// @notice The symbol for this smart contract.
    string public symbol = "AGI";

    /// @notice List of all gameItemAttribute structs representing all game items.
    GameItemAttributes[] public allGameItemAttributes;

    /// @notice The address that recieves funds of purchased game items.
    address public treasuryAddress;

    /// The address that has owner privileges (initially the contract deployer).
    address _ownerAddress;

    /// Total number of game items.
    uint256 _itemCount = 0;    

    /// @dev The Neuron contract instance.
    Neuron _neuronInstance;

    /*//////////////////////////////////////////////////////////////
                                MAPPINGS
    //////////////////////////////////////////////////////////////*/ 

    /// @notice Mapping of address to tokenId to get remaining allowance.
    mapping(address => mapping(uint256 => uint256)) public allowanceRemaining;

    /// @notice Mapping of address to tokenId to get replenish timestamp.
    mapping(address => mapping(uint256 => uint256)) public dailyAllowanceReplenishTime;

    /// @notice Mapping tracking addresses allowed to burn game items.
    mapping(address => bool) public allowedBurningAddresses;

    /// @notice Mapping tracking addresses allowed to manage game items.
    mapping(address => bool) public isAdmin;

    /// @notice Mapping of token id to the token URI
    mapping(uint256 => string) private _tokenURIs;

    /*//////////////////////////////////////////////////////////////
                               CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /// @notice Sets the owner address and the isAdmin mapping to true for the owner address.
    /// @param ownerAddress Address of contract deployer.
    /// @param treasuryAddress_ Address of admin signer for messages.
    constructor(address ownerAddress, address treasuryAddress_) ERC1155("https://ipfs.io/ipfs/") {
        _ownerAddress = ownerAddress;
        treasuryAddress = treasuryAddress_;
        isAdmin[_ownerAddress] = true;
    }

    /*//////////////////////////////////////////////////////////////
                            EXTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/    

    /// @notice Transfers ownership from one address to another.
    /// @dev Only the owner address is authorized to call this function.
    /// @param newOwnerAddress The address of the new owner
    function transferOwnership(address newOwnerAddress) external {
        require(msg.sender == _ownerAddress);
        _ownerAddress = newOwnerAddress;
    }

    /// @notice Adjusts admin access for a user.
    /// @dev Only the owner address is authorized to call this function.
    /// @param adminAddress The address of the admin.
    /// @param access Whether the address has admin access or not.
    function adjustAdminAccess(address adminAddress, bool access) external {
        require(msg.sender == _ownerAddress);
        isAdmin[adminAddress] = access;
    }  

    /// @notice Adjusts whether the game item can be transferred or not
    /// @dev Only the owner address is authorized to call this function.
    /// @param tokenId The token id for the specific game item being adjusted.
    /// @param transferable Whether the game item is transferable or not
    function adjustTransferability(uint256 tokenId, bool transferable) external {
        require(msg.sender == _ownerAddress);
        allGameItemAttributes[tokenId].transferable = transferable;
        if (transferable) {
          emit Unlocked(tokenId);
        } else {
          emit Locked(tokenId);
        }
    }

    /// @notice Sets the Neuron contract address and instantiates the contract.
    /// @dev Only the owner address is authorized to call this function.
    /// @param nrnAddress The address of the Neuron contract.
    function instantiateNeuronContract(address nrnAddress) external {
        require(msg.sender == _ownerAddress);
        _neuronInstance = Neuron(nrnAddress);
    }

    /// @notice Mints game items and assigns them to the caller.
    /// @param tokenId The ID of the game item to mint.
    /// @param quantity The quantity of game items to mint.
    function mint(uint256 tokenId, uint256 quantity) external {
        require(tokenId < _itemCount);
        uint256 price = allGameItemAttributes[tokenId].itemPrice * quantity;
        require(_neuronInstance.balanceOf(msg.sender) >= price, "Not enough NRN for purchase");
        require(
            allGameItemAttributes[tokenId].finiteSupply == false || 
            (
                allGameItemAttributes[tokenId].finiteSupply == true && 
                quantity <= allGameItemAttributes[tokenId].itemsRemaining
            )
        );
        require(
            dailyAllowanceReplenishTime[msg.sender][tokenId] <= block.timestamp || 
            quantity <= allowanceRemaining[msg.sender][tokenId]
        );

        _neuronInstance.approveSpender(msg.sender, price);
        bool success = _neuronInstance.transferFrom(msg.sender, treasuryAddress, price);
        if (success) {
            if (dailyAllowanceReplenishTime[msg.sender][tokenId] <= block.timestamp) {
                _replenishDailyAllowance(tokenId);
            }
            allowanceRemaining[msg.sender][tokenId] -= quantity;
            if (allGameItemAttributes[tokenId].finiteSupply) {
                allGameItemAttributes[tokenId].itemsRemaining -= quantity;
            }
            _mint(msg.sender, tokenId, quantity, bytes("random"));
            emit BoughtItem(msg.sender, tokenId, quantity);
        }
    }

    /*//////////////////////////////////////////////////////////////
                            PUBLIC FUNCTIONS
    //////////////////////////////////////////////////////////////*/    

    /// @notice Sets the allowed burning addresses.
    /// @dev Only the admins are authorized to call this function.
    /// @param newBurningAddress The address to allow for burning.
    function setAllowedBurningAddresses(address newBurningAddress) public {
        require(isAdmin[msg.sender]);
        allowedBurningAddresses[newBurningAddress] = true;
    }

    /// @notice Sets the token URI for a game item
    /// @dev Only the admins are authorized to call this function.
    /// @param tokenId The token id for the specific game item being queried.    
    /// @param _tokenURI The token id to be set
    function setTokenURI(uint256 tokenId, string memory _tokenURI) public {
        require(isAdmin[msg.sender]);
        _tokenURIs[tokenId] = _tokenURI;
    }

    /// @notice Creates a new game item with the specified attributes.
    /// @dev Only the admins are authorized to call this function.
    /// @param name_ The name of the game item.
    /// @param tokenURI The URI of the game item.
    /// @param finiteSupply Determines if the game item has a finite supply.
    /// @param transferable Boolean of whether or not the game item can be transferred
    /// @param itemsRemaining The number of remaining items for the game item.
    /// @param itemPrice The price of the game item.
    /// @param dailyAllowance The daily allowance for the game item.
    function createGameItem(
        string memory name_,
        string memory tokenURI,
        bool finiteSupply,
        bool transferable,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance
    ) 
        public 
    {
        require(isAdmin[msg.sender]);
        allGameItemAttributes.push(
            GameItemAttributes(
                name_,
                finiteSupply,
                transferable,
                itemsRemaining,
                itemPrice,
                dailyAllowance
            )
        );
        if (!transferable) {
          emit Locked(_itemCount);
        }
        setTokenURI(_itemCount, tokenURI);
        _itemCount += 1;
    }

    /// @notice Burns a specified amount of game items from an account.
    /// @dev Only addresses listed in allowedBurningAddresses are authorized to call this function.
    /// @param account The account from which the game items will be burned.
    /// @param tokenId The ID of the game item.
    /// @param amount The amount of game items to burn.
    function burn(address account, uint256 tokenId, uint256 amount) public {
        require(allowedBurningAddresses[msg.sender]);
        _burn(account, tokenId, amount);
    }

    /// @notice Returns the URI where the contract metadata is stored.
    /// @return URI where the contract metadata is stored.
    function contractURI() public pure returns (string memory) {
        return "ipfs://bafybeih3witscmml3padf4qxbea5jh4rl2xp67aydqvqsxmyuzipwtpnii";
    }

    /// @notice Override the uri function to return the custom URI for each token
    /// @param tokenId The token id for the specific game item being queried.
    /// @return tokenURI The URI for the game item metadata.
    function uri(uint256 tokenId) public view override returns (string memory) {
        string memory customURI = _tokenURIs[tokenId];
        if (bytes(customURI).length > 0) {
            return customURI;
        }
        return super.uri(tokenId);
    }        

    /// @notice Gets the amount of a game item that a user is still able to mint for the day
    /// @param owner The user's address.
    /// @param tokenId The token id for the specific game item being queried.
    /// @return remaining number of items that can be minted for the day.
    function getAllowanceRemaining(address owner, uint256 tokenId) public view returns (uint256) {
        uint256 remaining = allowanceRemaining[owner][tokenId];
        if (dailyAllowanceReplenishTime[owner][tokenId] <= block.timestamp) {
            remaining = allGameItemAttributes[tokenId].dailyAllowance;
        }
        return remaining;
    }

    /// @notice Returns the remaining supply of a game item with the specified tokenId.
    /// @param tokenId The ID of the game item.
    /// @return Remaining items for the queried token ID.
    function remainingSupply(uint256 tokenId) public view returns (uint256) {
        return allGameItemAttributes[tokenId].itemsRemaining;
    }

    /// @notice Returns the total number of unique game tokens outstanding.
    /// @return Total number of unique game tokens.
    function uniqueTokensOutstanding() public view returns (uint256) {
        return allGameItemAttributes.length;
    }

    /// @notice Safely transfers an NFT from one address to another.
    /// @dev Added a check to see if the game item is transferable.
    function safeTransferFrom(
        address from, 
        address to, 
        uint256 tokenId,
        uint256 amount,
        bytes memory data
    ) 
        public 
        override(ERC1155)
    {
        require(allGameItemAttributes[tokenId].transferable);
        super.safeTransferFrom(from, to, tokenId, amount, data);
    }

    /*//////////////////////////////////////////////////////////////
                            PRIVATE FUNCTIONS
    //////////////////////////////////////////////////////////////*/    

    /// @notice Replenishes the daily allowance for the specified game item token.
    /// @dev This function is called when a user buys a game item after the replenish interval has passed.
    /// @param tokenId The ID of the game item token.
    function _replenishDailyAllowance(uint256 tokenId) private {
        allowanceRemaining[msg.sender][tokenId] = allGameItemAttributes[tokenId].dailyAllowance;
        dailyAllowanceReplenishTime[msg.sender][tokenId] = uint32(block.timestamp + 1 days);
    }    
}"},"src/MergingPool.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;

import { FighterFarm } from "./FighterFarm.sol";

/// @title MergingPool
/// @author ArenaX Labs Inc.
/// @notice This contract allows users to potentially earn a new fighter NFT.
contract MergingPool {

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Event emitted when merging pool points are added.
    event PointsAdded(uint256 tokenId, uint256 points);

    /// @notice Event emitted when claimed.
    event Claimed(address claimer, uint32 amount);

    /*//////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    /// @notice Number of winners per period.
    uint256 public winnersPerPeriod = 2;

    /// @notice Current roundId.
    uint256 public roundId = 0;

    /// @notice Total points.
    uint256 public totalPoints = 0;    

    /// The address that has owner privileges (initially the contract deployer).
    address _ownerAddress;

    /// The address of the ranked battle contract.
    address _rankedBattleAddress;

    /// @dev The fighter farm contract instance.
    FighterFarm _fighterFarmInstance;

    /*//////////////////////////////////////////////////////////////
                                MAPPINGS
    //////////////////////////////////////////////////////////////*/

    /// @notice Maps the user address to the number of rounds they've claimed for
    mapping(address => uint32) public numRoundsClaimed;

    /// @notice Mapping of address to fighter points.
    mapping(uint256 => uint256) public fighterPoints;

    /// @notice Mapping of roundId to winner addresses list.
    mapping(uint256 => address[]) public winnerAddresses;    

    /// @notice Mapping of round id to an indication of whether winners have been selected yet.
    mapping(uint256 => bool) public isSelectionComplete;

    /// @notice Mapping of address to admin status.
    mapping(address => bool) public isAdmin;

    /*//////////////////////////////////////////////////////////////
                               CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /// @notice Sets the address for the owner and ranked battle smart contract.
    /// Instantiates the fighter farm contract and sets the owner to be an admin
    /// @param ownerAddress Address of contract deployer.
    /// @param rankedBattleAddress Address of ranked battle contract.
    /// @param fighterFarmAddress Address of fighter farm contract.
    constructor(
        address ownerAddress, 
        address rankedBattleAddress, 
        address fighterFarmAddress
    ) {
        _ownerAddress = ownerAddress;
        _rankedBattleAddress = rankedBattleAddress;
        _fighterFarmInstance = FighterFarm(fighterFarmAddress);
        isAdmin[_ownerAddress] = true;
    }

    /*//////////////////////////////////////////////////////////////
                            EXTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @notice Transfers ownership from one address to another.
    /// @dev Only the owner address is authorized to call this function.
    /// @param newOwnerAddress The address of the new owner
    function transferOwnership(address newOwnerAddress) external {
        require(msg.sender == _ownerAddress);
        _ownerAddress = newOwnerAddress;
    }

    /// @notice Adjusts admin access for a user.
    /// @dev Only the owner address is authorized to call this function.
    /// @param adminAddress The address of the admin.
    /// @param access Whether the address has admin access or not.
    function adjustAdminAccess(address adminAddress, bool access) external {
        require(msg.sender == _ownerAddress);
        isAdmin[adminAddress] = access;
    }   

    /// @notice Change the number of winners per competition period.
    /// @dev Only admins are authorized to call this function.
    /// @param newWinnersPerPeriodAmount The new number of winners per period.
    function updateWinnersPerPeriod(uint256 newWinnersPerPeriodAmount) external {
        require(isAdmin[msg.sender]);
        winnersPerPeriod = newWinnersPerPeriodAmount;
    }    

    /// @notice Allows the admin to pick the winners for the current round.
    /// @dev Only admins are authorized to call this function.
    /// @dev The number of winners must match the expected number of winners per period.
    /// @dev The function will check that there are no existing winners for the current round.
    /// @dev The function will update the winnerAddresses mapping with the addresses of the winners.
    /// @dev The function will also reset the fighterPoints of the winners to zero.
    /// @param winners The array of token IDs representing the winners.
    function pickWinner(uint256[] calldata winners) external {
        require(isAdmin[msg.sender]);
        require(winners.length == winnersPerPeriod, "Incorrect number of winners");
        require(!isSelectionComplete[roundId], "Winners are already selected");
        uint256 winnersLength = winners.length;
        address[] memory currentWinnerAddresses = new address[](winnersLength);
        for (uint256 i = 0; i < winnersLength; i++) {
            currentWinnerAddresses[i] = _fighterFarmInstance.ownerOf(winners[i]);
            totalPoints -= fighterPoints[winners[i]];
            fighterPoints[winners[i]] = 0;
        }
        winnerAddresses[roundId] = currentWinnerAddresses;
        isSelectionComplete[roundId] = true;
        roundId += 1;
    }

    /// @notice Allows the user to batch claim rewards for multiple rounds.
    /// @dev The user can only claim rewards once for each round.
    /// @param modelURIs The array of model URIs corresponding to each round and winner address.
    /// @param modelTypes The array of model types corresponding to each round and winner address.
    /// @param customAttributes Array with [element, weight] of the newly created fighter.
    function claimRewards(
        string[] calldata modelURIs, 
        string[] calldata modelTypes,
        uint256[2][] calldata customAttributes
    ) 
        external 
    {
        uint256 winnersLength;
        uint32 claimIndex = 0;
        uint32 lowerBound = numRoundsClaimed[msg.sender];
        for (uint32 currentRound = lowerBound; currentRound < roundId; currentRound++) {
            numRoundsClaimed[msg.sender] += 1;
            winnersLength = winnerAddresses[currentRound].length;
            for (uint32 j = 0; j < winnersLength; j++) {
                if (msg.sender == winnerAddresses[currentRound][j]) {
                    _fighterFarmInstance.mintFromMergingPool(
                        msg.sender,
                        modelURIs[claimIndex],
                        modelTypes[claimIndex],
                        customAttributes[claimIndex]
                    );
                    claimIndex += 1;
                }
            }
        }
        if (claimIndex > 0) {
            emit Claimed(msg.sender, claimIndex);
        }
    }

    /// @notice Gets the unclaimed rewards for a specific address.
    /// @param claimer The address of the claimer.
    /// @return numRewards The amount of unclaimed fighters.
    function getUnclaimedRewards(address claimer) external view returns(uint256) {
        uint256 winnersLength;
        uint256 numRewards = 0;
        uint32 lowerBound = numRoundsClaimed[claimer];
        for (uint32 currentRound = lowerBound; currentRound < roundId; currentRound++) {
            winnersLength = winnerAddresses[currentRound].length;
            for (uint32 j = 0; j < winnersLength; j++) {
                if (claimer == winnerAddresses[currentRound][j]) {
                    numRewards += 1;
                }
            }
        }
        return numRewards;
    }

    /*//////////////////////////////////////////////////////////////
                            PUBLIC FUNCTIONS
    //////////////////////////////////////////////////////////////*/    

    /// @notice Add merging pool points to a fighter.
    /// @dev Only the rankedBattle contract address can call this function.
    /// @param tokenId The ID of the fighter token.
    /// @param points The number of points to be added to the fighter.
    function addPoints(uint256 tokenId, uint256 points) public {
        require(msg.sender == _rankedBattleAddress, "Not Ranked Battle contract address");
        fighterPoints[tokenId] += points;
        totalPoints += points;
        emit PointsAdded(tokenId, points);
    }

    /// @notice Retrieves the points for multiple fighters up to the specified maximum token ID.
    /// @param maxId The maximum token ID up to which the points will be retrieved.
    /// @return An array of points corresponding to the fighters' token IDs.
    function getFighterPoints(uint256 maxId) public view returns(uint256[] memory) {
        uint256[] memory points = new uint256[](1);
        for (uint256 i = 0; i < maxId; i++) {
            points[i] = fighterPoints[i];
        }
        return points;
    }
}"},"src/Neuron.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/// @title Neuron
/// @author ArenaX Labs Inc.
/// @notice ERC20 token contract representing Neuron (NRN) tokens.
/// @dev The Neuron token is used for AI Arena's in-game economy.
contract Neuron is ERC20, AccessControl {

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Event emitted when tokens are claimed.
    event TokensClaimed(address user, uint256 amount);

    /// @notice Event emitted when tokens are minted.
    event TokensMinted(address user, uint256 amount);    

    /*//////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    /// @notice Role for minting tokens.
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    /// @notice Role for spending tokens.
    bytes32 public constant SPENDER_ROLE = keccak256("SPENDER_ROLE");

    /// @notice Role for staking tokens.
    bytes32 public constant STAKER_ROLE = keccak256("STAKER_ROLE");

    /// @notice Initial supply of NRN tokens to be minted to the treasury.
    uint256 public constant INITIAL_TREASURY_MINT = 10**18 * 10**8 * 2;

    /// @notice Initial supply of NRN tokens to be minted and distributed to contributors.
    uint256 public constant INITIAL_CONTRIBUTOR_MINT = 10**18 * 10**8 * 5;

    /// @notice Maximum supply of NRN tokens.
    uint256 public constant MAX_SUPPLY = 10**18 * 10**9;

    /// @notice The address of treasury.
    address public treasuryAddress;

    /// The address that has owner privileges (initially the contract deployer).
    address _ownerAddress;

    /*//////////////////////////////////////////////////////////////
                                MAPPINGS
    //////////////////////////////////////////////////////////////*/

    /// @notice Mapping of address to admin status.
    mapping(address => bool) public isAdmin;

    /*//////////////////////////////////////////////////////////////
                               CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /// @notice Grants roles to the ranked battle contract. 
    /// @notice Mints the initial supply of tokens.
    /// @param ownerAddress The address of the owner who deploys the contract
    /// @param treasuryAddress_ The address of the community treasury
    /// @param contributorAddress The address that will distribute NRNs to early contributors when 
    /// the initial supply is minted.
    constructor(address ownerAddress, address treasuryAddress_, address contributorAddress)
        ERC20("Neuron", "NRN")
    {
        _ownerAddress = ownerAddress;
        treasuryAddress = treasuryAddress_;
        isAdmin[_ownerAddress] = true;
        _mint(treasuryAddress, INITIAL_TREASURY_MINT);
        _mint(contributorAddress, INITIAL_CONTRIBUTOR_MINT);
    }

    /*//////////////////////////////////////////////////////////////
                            EXTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @notice Transfers ownership from one address to another.
    /// @dev Only the owner address is authorized to call this function.
    /// @param newOwnerAddress The address of the new owner
    function transferOwnership(address newOwnerAddress) external {
        require(msg.sender == _ownerAddress);
        _ownerAddress = newOwnerAddress;
    }

    /// @notice Adds a new address to the minter role.
    /// @dev Only the owner address is authorized to call this function.
    /// @param newMinterAddress The address to be added as a minter
    function addMinter(address newMinterAddress) external {
        require(msg.sender == _ownerAddress);
        _setupRole(MINTER_ROLE, newMinterAddress);
    }

    /// @notice Adds a new address to the staker role.
    /// @dev Only the owner address is authorized to call this function.
    /// @param newStakerAddress The address to be added as a staker
    function addStaker(address newStakerAddress) external {
        require(msg.sender == _ownerAddress);
        _setupRole(STAKER_ROLE, newStakerAddress);
    }

    /// @notice Adds a new address to the spender role.
    /// @dev Only the owner address is authorized to call this function.
    /// @param newSpenderAddress The address to be added as a spender
    function addSpender(address newSpenderAddress) external {
        require(msg.sender == _ownerAddress);
        _setupRole(SPENDER_ROLE, newSpenderAddress);
    }

    /// @notice Adjusts admin access for a user.
    /// @dev Only the owner address is authorized to call this function.
    /// @param adminAddress The address of the admin.
    /// @param access Whether the address has admin access or not.
    function adjustAdminAccess(address adminAddress, bool access) external {
        require(msg.sender == _ownerAddress);
        isAdmin[adminAddress] = access;
    }  

    /// @notice Sets up the allowance from the treasury address to transfer to each recipient address.
    /// @dev Only admins are authorized to call this function.
    /// @param recipients The array of recipient addresses
    /// @param amounts The array of corresponding amounts for each recipient
    function setupAirdrop(address[] calldata recipients, uint256[] calldata amounts) external {
        require(isAdmin[msg.sender]);
        require(recipients.length == amounts.length);
        uint256 recipientsLength = recipients.length;
        for (uint32 i = 0; i < recipientsLength; i++) {
            _approve(treasuryAddress, recipients[i], amounts[i]);
        }
    }

    /// @notice Claims the specified amount of tokens from the treasury address to the caller's address.
    /// @param amount The amount to be claimed
    function claim(uint256 amount) external {
        require(
            allowance(treasuryAddress, msg.sender) >= amount, 
            "ERC20: claim amount exceeds allowance"
        );
        transferFrom(treasuryAddress, msg.sender, amount);
        emit TokensClaimed(msg.sender, amount);
    }

    /*//////////////////////////////////////////////////////////////
                            PUBLIC FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @notice Mints the specified amount of tokens to the given address.
    /// @dev The caller must have the minter role.
    /// @param to The address to which the tokens will be minted.
    /// @param amount The amount of tokens to be minted.
    function mint(address to, uint256 amount) public virtual {
        require(totalSupply() + amount < MAX_SUPPLY, "Trying to mint more than the max supply");
        require(hasRole(MINTER_ROLE, msg.sender), "ERC20: must have minter role to mint");
        _mint(to, amount);
    }

    /// @notice Burns the specified amount of tokens from the caller's address.
    /// @param amount The amount of tokens to be burned.
    function burn(uint256 amount) public virtual {
        _burn(msg.sender, amount);
    }

    /// @notice Approves the specified amount of tokens for the spender address.
    /// @dev The caller must have the spender role.
    /// @param account The account for which to approve the allowance.
    /// @param amount The amount of tokens to be approved.
    function approveSpender(address account, uint256 amount) public {
        require(
            hasRole(SPENDER_ROLE, msg.sender), 
            "ERC20: must have spender role to approve spending"
        );
        _approve(account, msg.sender, amount);
    }

    /// @notice Approves the specified amount of tokens for the staker address.
    /// @dev The caller must have the staker role.
    /// @param owner The owner of the tokens.
    /// @param spender The address for which to approve the allowance.
    /// @param amount The amount of tokens to be approved.
    function approveStaker(address owner, address spender, uint256 amount) public {
        require(
            hasRole(STAKER_ROLE, msg.sender), 
            "ERC20: must have staker role to approve staking"
        );
        _approve(owner, spender, amount);
    }

    /// @notice Burns the specified amount of tokens from the account address.
    /// The caller must have an allowance greater than or equal to the amount.
    /// @param account The account from which to burn the tokens
    /// @param amount The amount of tokens to be burned
    function burnFrom(address account, uint256 amount) public virtual {
        require(
            allowance(account, msg.sender) >= amount, 
            "ERC20: burn amount exceeds allowance"
        );
        uint256 decreasedAllowance = allowance(account, msg.sender) - amount;
        _burn(account, amount);
        _approve(account, msg.sender, decreasedAllowance);
    }

}
"},"src/RankedBattle.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;

import { FighterFarm } from "./FighterFarm.sol";
import { VoltageManager } from "./VoltageManager.sol";
import { MergingPool } from "./MergingPool.sol";
import { Neuron } from "./Neuron.sol";
import { StakeAtRisk } from "./StakeAtRisk.sol";
import { FixedPointMathLib } from './FixedPointMathLib.sol';

/// @title RankedBattle
/// @author ArenaX Labs Inc.
/// @notice This contract provides functionality for staking NRN tokens on fighters, 
/// tracking battle records, calculating and distributing rewards based on battle outcomes 
/// and staked amounts, and allowing claiming of accumulated rewards.
contract RankedBattle {

    /// @dev Extend functionality of the FixedPointMathLib library to the uint data type.
    using FixedPointMathLib for uint;

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Event emitted when staked.
    event Staked(address from, uint256 amount);

    /// @notice Event emitted when unstaked.
    event Unstaked(address from, uint256 amount);

    /// @notice Event emitted when claimed.
    event Claimed(address claimer, uint256 amount);

    /// @notice Event emitted when points are added or subtracted from a fighter.
    event PointsChanged(uint256 tokenId, uint256 points, bool increased);    

    /*//////////////////////////////////////////////////////////////
                                STRUCTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Struct for battle record.
    struct BattleRecord {
        uint32 wins;
        uint32 ties;
        uint32 loses;
    }

    /*//////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    /// @notice Voltage cost per match initiated
    uint8 public constant VOLTAGE_COST = 10;

    /// @notice Number of total battles.
    uint256 public totalBattles = 0;

    /// @notice Number of overall staked amount.
    uint256 public globalStakedAmount = 0;

    /// @notice Current round number.
    uint256 public roundId = 0;

    /// @notice Amount of basis points that get taken away from a player's stake when they lose in 
    /// a point deficit.
    uint256 public bpsLostPerLoss = 10;

    /// The StakeAtRisk contract address.
    address _stakeAtRiskAddress;

    /// The address that has owner privileges (initially the contract deployer).
    address _ownerAddress;

    /// @notice The address in charge of updating battle records.
    address _gameServerAddress;

    /*//////////////////////////////////////////////////////////////
                            CONTRACT INSTANCES
    //////////////////////////////////////////////////////////////*/ 

    /// @notice The neuron contract instance.
    Neuron _neuronInstance;

    /// @notice The fighter farm contract instance.
    FighterFarm _fighterFarmInstance;

    /// @notice The voltage manager contract instance.
    VoltageManager _voltageManagerInstance;

    /// @notice The merging pool contract instance.
    MergingPool _mergingPoolInstance;

    /// @notice The stake at risk contract instance.
    StakeAtRisk _stakeAtRiskInstance;

    /*//////////////////////////////////////////////////////////////
                                MAPPINGS
    //////////////////////////////////////////////////////////////*/

    /// @notice Maps addresses that are admins.
    mapping(address => bool) public isAdmin;

    /// @notice Mapping of token id to battle record struct.
    mapping(uint256 => BattleRecord) public fighterBattleRecord;

    /// @notice Mapping of address to the amount of NRNs they have claimed.
    mapping(address => uint256) public amountClaimed;

    /// @notice Maps the user address to the number of rounds they've claimed for
    mapping(address => uint32) public numRoundsClaimed;

    /// @notice Maps address to round ID to track accumulated points.
    mapping(address => mapping(uint256 => uint256)) public accumulatedPointsPerAddress;

    /// @notice Maps token ID to round ID to track accumulated points.
    mapping(uint256 => mapping(uint256 => uint256)) public accumulatedPointsPerFighter;

    /// @notice Maps round ID to total accumulated points.
    mapping(uint256 => uint256) public totalAccumulatedPoints;

    /// @notice Mapping of roundID to nrn distribution amount for a ranked period.
    mapping(uint256 => uint256) public rankedNrnDistribution;

    /// @notice Maps the token ID to the round ID and indicates whether it is Unstaked or not.
    mapping(uint256 => mapping(uint256 => bool)) public hasUnstaked;

    /// @notice Mapping of token id to staked amount.
    mapping(uint256 => uint256) public amountStaked;

    /// @notice Mapping of token id to staking factor.
    mapping(uint256 => uint256) public stakingFactor;

    /// @notice Indicates whether we have calculated the staking factor for a given round and token.
    mapping(uint256 => mapping(uint256 => bool)) _calculatedStakingFactor;

    /*//////////////////////////////////////////////////////////////
                               CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /// @notice Initializes the contract by setting various addresses and instantiating 
    /// contract instances. It also designates the owner address as an admin. 
    /// @param ownerAddress Address of contract deployer.
    /// @param gameServerAddress The game server address.
    /// @param fighterFarmAddress Address of the FighterFarm contract.
    /// @param voltageManagerAddress Address of the VoltageManager contract.
    constructor(
      address ownerAddress, 
      address gameServerAddress,
      address fighterFarmAddress,
      address voltageManagerAddress
    ) {
        _ownerAddress = ownerAddress;
        _gameServerAddress = gameServerAddress;
        _fighterFarmInstance = FighterFarm(fighterFarmAddress);
        _voltageManagerInstance = VoltageManager(voltageManagerAddress);
        isAdmin[_ownerAddress] = true;
        rankedNrnDistribution[0] = 5000 * 10**18;
    }

    /*//////////////////////////////////////////////////////////////
                            EXTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @notice Transfers ownership from one address to another.
    /// @dev Only the owner address is authorized to call this function.
    /// @param newOwnerAddress The address of the new owner
    function transferOwnership(address newOwnerAddress) external {
        require(msg.sender == _ownerAddress);
        _ownerAddress = newOwnerAddress;
    }

    /// @notice Adjusts admin access for a user.
    /// @dev Only the owner address is authorized to call this function.
    /// @param adminAddress The address of the admin.
    /// @param access Whether the address has admin access or not.
    function adjustAdminAccess(address adminAddress, bool access) external {
        require(msg.sender == _ownerAddress);
        isAdmin[adminAddress] = access;
    }  

    /// @notice Sets the game server address.
    /// @dev Only the owner address is authorized to call this function.
    /// @param gameServerAddress The game server address.
    function setGameServerAddress(address gameServerAddress) external {
        require(msg.sender == _ownerAddress);
        _gameServerAddress = gameServerAddress;
    }

    /// @notice Sets the Stake at Risk contract address and instantiates the contract.
    /// @dev Only the owner address is authorized to call this function.
    /// @param stakeAtRiskAddress The address of the Stake At Risk contract.
    function setStakeAtRiskAddress(address stakeAtRiskAddress) external {
        require(msg.sender == _ownerAddress);
        _stakeAtRiskAddress = stakeAtRiskAddress;
        _stakeAtRiskInstance = StakeAtRisk(_stakeAtRiskAddress);
    }

    /// @notice Instantiates the neuron contract.
    /// @dev Only the owner address is authorized to call this function.
    /// @param nrnAddress The address of the Neuron contract.
    function instantiateNeuronContract(address nrnAddress) external {
        require(msg.sender == _ownerAddress);
        _neuronInstance = Neuron(nrnAddress);
    }

    /// @notice Instantiates the merging pool contract.
    /// @dev Only the owner address is authorized to call this function.
    /// @param mergingPoolAddress The address of the MergingPool contract.
    function instantiateMergingPoolContract(address mergingPoolAddress) external {
        require(msg.sender == _ownerAddress);
        _mergingPoolInstance = MergingPool(mergingPoolAddress);
    }

    /// @notice Sets the ranked nrn distribution amount for the current round.
    /// @dev Only admins are authorized to change the ranked NRN distribution.
    /// @dev newDistribution is NOT denominated in wei. As such, it is multiplied by 10**18.
    /// @param newDistribution The new distribution amount.
    function setRankedNrnDistribution(uint256 newDistribution) external {
        require(isAdmin[msg.sender]);
        rankedNrnDistribution[roundId] = newDistribution * 10**18;
    }

    /// @notice Sets the basis points lost per ranked match lost while in a point deficit.
    /// @dev Only admins are authorized to call this function.
    /// @param bpsLostPerLoss_ The basis points lost per loss.
    function setBpsLostPerLoss(uint256 bpsLostPerLoss_) external {
        require(isAdmin[msg.sender]);
        bpsLostPerLoss = bpsLostPerLoss_;
    }

    /// @notice Sets a new round, making claiming available for that round.
    /// @dev Only admins are authorized to move the round forward.
    function setNewRound() external {
        require(isAdmin[msg.sender]);
        require(totalAccumulatedPoints[roundId] > 0);
        roundId += 1;
        _stakeAtRiskInstance.setNewRound(roundId);
        rankedNrnDistribution[roundId] = rankedNrnDistribution[roundId - 1];
    }

    /// @notice Stakes NRN tokens.
    /// @param amount The amount of NRN tokens to stake.
    /// @param tokenId The ID of the fighter to stake.
    function stakeNRN(uint256 amount, uint256 tokenId) external {
        require(amount > 0, "Amount cannot be 0");
        require(_fighterFarmInstance.ownerOf(tokenId) == msg.sender, "Caller does not own fighter");
        require(_neuronInstance.balanceOf(msg.sender) >= amount, "Stake amount exceeds balance");
        require(hasUnstaked[tokenId][roundId] == false, "Cannot add stake after unstaking this round");

        _neuronInstance.approveStaker(msg.sender, address(this), amount);
        bool success = _neuronInstance.transferFrom(msg.sender, address(this), amount);
        if (success) {
            if (amountStaked[tokenId] == 0) {
                _fighterFarmInstance.updateFighterStaking(tokenId, true);
            }
            amountStaked[tokenId] += amount;
            globalStakedAmount += amount;
            stakingFactor[tokenId] = _getStakingFactor(
                tokenId, 
                _stakeAtRiskInstance.getStakeAtRisk(tokenId)
            );
            _calculatedStakingFactor[tokenId][roundId] = true;
            emit Staked(msg.sender, amount);
        }
    }

    /// @notice Unstakes NRN tokens.
    /// @param amount The amount of NRN tokens to unstake.
    /// @param tokenId The ID of the token to unstake.
    function unstakeNRN(uint256 amount, uint256 tokenId) external {
        require(_fighterFarmInstance.ownerOf(tokenId) == msg.sender, "Caller does not own fighter");
        if (amount > amountStaked[tokenId]) {
            amount = amountStaked[tokenId];
        }
        amountStaked[tokenId] -= amount;
        globalStakedAmount -= amount;
        stakingFactor[tokenId] = _getStakingFactor(
            tokenId, 
            _stakeAtRiskInstance.getStakeAtRisk(tokenId)
        );
        _calculatedStakingFactor[tokenId][roundId] = true;
        hasUnstaked[tokenId][roundId] = true;
        bool success = _neuronInstance.transfer(msg.sender, amount);
        if (success) {
            if (amountStaked[tokenId] == 0) {
                _fighterFarmInstance.updateFighterStaking(tokenId, false);
            }
            emit Unstaked(msg.sender, amount);
        }
    }

    /// @notice Claims NRN tokens for the specified rounds.
    /// @dev Caller can only claim once per round.
    function claimNRN() external {
        require(numRoundsClaimed[msg.sender] < roundId, "Already claimed NRNs for this period");
        uint256 claimableNRN = 0;
        uint256 nrnDistribution;
        uint32 lowerBound = numRoundsClaimed[msg.sender];
        for (uint32 currentRound = lowerBound; currentRound < roundId; currentRound++) {
            nrnDistribution = getNrnDistribution(currentRound);
            claimableNRN += (
                accumulatedPointsPerAddress[msg.sender][currentRound] * nrnDistribution   
            ) / totalAccumulatedPoints[currentRound];
            numRoundsClaimed[msg.sender] += 1;
        }
        if (claimableNRN > 0) {
            amountClaimed[msg.sender] += claimableNRN;
            _neuronInstance.mint(msg.sender, claimableNRN);
            emit Claimed(msg.sender, claimableNRN);
        }
    }

    /// @notice Updates the battle record for a fighter.
    /// @dev Only the game server address is authorized to update the battle record.
    /// @dev Only the fighter that initiates the battle expends voltage on the match.
    /// @dev Only fighters that have NRN staked are able to earn points.
    /// @param tokenId The ID of the fighter.
    /// @param mergingPortion The portion of points that get redirected to the merging pool.
    /// @param battleResult The result of the battle.
    /// @param eloFactor Multiple derived from ELO to be applied to the base points earned.
    /// @param initiatorBool Whether this was the fighter that initiated the battle or not
    function updateBattleRecord(
        uint256 tokenId, 
        uint256 mergingPortion,
        uint8 battleResult,
        uint256 eloFactor,
        bool initiatorBool
    ) 
        external 
    {   
        require(msg.sender == _gameServerAddress);
        require(mergingPortion <= 100);
        address fighterOwner = _fighterFarmInstance.ownerOf(tokenId);
        require(
            !initiatorBool ||
            _voltageManagerInstance.ownerVoltageReplenishTime(fighterOwner) <= block.timestamp || 
            _voltageManagerInstance.ownerVoltage(fighterOwner) >= VOLTAGE_COST
        );

        _updateRecord(tokenId, battleResult);
        uint256 stakeAtRisk = _stakeAtRiskInstance.getStakeAtRisk(tokenId);
        if (amountStaked[tokenId] + stakeAtRisk > 0) {
            _addResultPoints(battleResult, tokenId, eloFactor, mergingPortion, fighterOwner);
        }
        if (initiatorBool) {
            _voltageManagerInstance.spendVoltage(fighterOwner, VOLTAGE_COST);
        }
        totalBattles += 1;
    }

    /// @notice Gets the battle record for a token.
    /// @param tokenId The ID of the token.
    /// @return Record which is comprised of wins, ties, and losses for the token.
    function getBattleRecord(uint256 tokenId) external view returns(uint32, uint32, uint32) {
      return (
          fighterBattleRecord[tokenId].wins, 
          fighterBattleRecord[tokenId].ties, 
          fighterBattleRecord[tokenId].loses
      );
    }

    /// @notice Gets the staking data for a token.
    /// @return Round id, nrns to be distributed, and total point tally
    function getCurrentStakingData() external view returns(uint256, uint256, uint256) {
      return (
          roundId,
          rankedNrnDistribution[roundId], 
          totalAccumulatedPoints[roundId]
      );
    }

    /*//////////////////////////////////////////////////////////////
                            PUBLIC FUNCTIONS
    //////////////////////////////////////////////////////////////*/    

    /// @notice Retrieves the nrn distribution amount for the given round ID.
    /// @param roundId_ The round ID for which to get the nrn distribution.
    /// @return Distribution amount for the specified round ID.
    function getNrnDistribution(uint256 roundId_) public view returns(uint256) {
        return rankedNrnDistribution[roundId_];
    }

    /// @notice Gets the unclaimed NRN tokens for a specific address.
    /// @param claimer The address of the claimer.
    /// @return The amount of unclaimed NRN tokens.
    function getUnclaimedNRN(address claimer) public view returns(uint256) {
        uint256 claimableNRN = 0;
        uint256 nrnDistribution;   
        uint32 lowerBound = numRoundsClaimed[claimer];
        for (uint32 i = lowerBound; i < roundId; i++) {
            nrnDistribution = getNrnDistribution(i);
            claimableNRN += (
                accumulatedPointsPerAddress[claimer][i] * nrnDistribution
            ) / totalAccumulatedPoints[i];
        }
        return claimableNRN;
    } 

    /*//////////////////////////////////////////////////////////////
                            PRIVATE FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @notice Adds result points for a battle, based on the battle result, ELO factor, and merging portion.
    /// @dev This function is called internally and is not accessible externally.
    /// @dev There are 5 scenarios to be aware of:
    /// @dev 1) Win + no stake-at-risk = Increase points balance
    /// @dev 2) Win + stake-at-risk = Reclaim some of the stake that is at risk
    /// @dev 3) Lose + positive point balance = Deduct from the point balance
    /// @dev 4) Lose + no points = Move some of their NRN staked to the Stake At Risk contract
    /// @dev 5) Tie = no consequence
    /// @param battleResult The result of the battle (0: win, 1: tie, 2: loss).
    /// @param tokenId The ID of the token participating in the battle.
    /// @param eloFactor Multiple derived from ELO to be applied to the base points earned.
    /// @param mergingPortion The portion of points that get redirected to the merging pool.
    /// @param fighterOwner The address which owns the fighter whos points are being altered.
    function _addResultPoints(
        uint8 battleResult, 
        uint256 tokenId, 
        uint256 eloFactor, 
        uint256 mergingPortion,
        address fighterOwner
    ) 
        private 
    {
        uint256 stakeAtRisk;
        uint256 curStakeAtRisk;
        uint256 points = 0;

        /// Check how many NRNs the fighter has at risk
        stakeAtRisk = _stakeAtRiskInstance.getStakeAtRisk(tokenId);

        /// Calculate the staking factor if it has not already been calculated for this round 
        if (_calculatedStakingFactor[tokenId][roundId] == false) {
            stakingFactor[tokenId] = _getStakingFactor(tokenId, stakeAtRisk);
            _calculatedStakingFactor[tokenId][roundId] = true;
        }

        /// Potential amount of NRNs to put at risk or retrieve from the stake-at-risk contract
        curStakeAtRisk = (bpsLostPerLoss * (amountStaked[tokenId] + stakeAtRisk)) / 10**4;
        if (battleResult == 0) {
            /// If the user won the match

            /// If the user has no NRNs at risk, then they can earn points
            if (stakeAtRisk == 0) {
                points = stakingFactor[tokenId] * eloFactor;
            }

            /// Divert a portion of the points to the merging pool
            uint256 mergingPoints = (points * mergingPortion) / 100;
            points -= mergingPoints;
            _mergingPoolInstance.addPoints(tokenId, mergingPoints);

            /// Do not allow users to reclaim more NRNs than they have at risk
            if (curStakeAtRisk > stakeAtRisk) {
                curStakeAtRisk = stakeAtRisk;
            }

            /// If the user has stake-at-risk for their fighter, reclaim a portion
            /// Reclaiming stake-at-risk puts the NRN back into their staking pool
            if (curStakeAtRisk > 0) {
                _stakeAtRiskInstance.reclaimNRN(curStakeAtRisk, tokenId, fighterOwner);
                amountStaked[tokenId] += curStakeAtRisk;
            }

            /// Add points to the fighter for this round
            accumulatedPointsPerFighter[tokenId][roundId] += points;
            accumulatedPointsPerAddress[fighterOwner][roundId] += points;
            totalAccumulatedPoints[roundId] += points;
            if (points > 0) {
                emit PointsChanged(tokenId, points, true);
            }
        } else if (battleResult == 2) {
            /// If the user lost the match

            /// Do not allow users to lose more NRNs than they have in their staking pool
            if (curStakeAtRisk > amountStaked[tokenId]) {
                curStakeAtRisk = amountStaked[tokenId];
            }
            if (accumulatedPointsPerFighter[tokenId][roundId] > 0) {
                /// If the fighter has a positive point balance for this round, deduct points 
                points = stakingFactor[tokenId] * eloFactor;
                if (points > accumulatedPointsPerFighter[tokenId][roundId]) {
                    points = accumulatedPointsPerFighter[tokenId][roundId];
                }
                accumulatedPointsPerFighter[tokenId][roundId] -= points;
                accumulatedPointsPerAddress[fighterOwner][roundId] -= points;
                totalAccumulatedPoints[roundId] -= points;
                if (points > 0) {
                    emit PointsChanged(tokenId, points, false);
                }
            } else {
                /// If the fighter does not have any points for this round, NRNs become at risk of being lost
                bool success = _neuronInstance.transfer(_stakeAtRiskAddress, curStakeAtRisk);
                if (success) {
                    _stakeAtRiskInstance.updateAtRiskRecords(curStakeAtRisk, tokenId, fighterOwner);
                    amountStaked[tokenId] -= curStakeAtRisk;
                }
            }
        }
    }

    /// @notice Updates the battle record for a token.
    /// @param tokenId The ID of the token.
    /// @param battleResult The result of the battle.
    function _updateRecord(uint256 tokenId, uint8 battleResult) private {
        if (battleResult == 0) {
            fighterBattleRecord[tokenId].wins += 1;
        } else if (battleResult == 1) {
            fighterBattleRecord[tokenId].ties += 1;
        } else if (battleResult == 2) {
            fighterBattleRecord[tokenId].loses += 1;
        }
    }

    /// @notice Gets the staking factor for a token.
    /// @param tokenId The ID of the token.
    /// @param stakeAtRisk The amount of stake they have at risk.
    /// @return Staking factor.
    function _getStakingFactor(
        uint256 tokenId, 
        uint256 stakeAtRisk
    ) 
        private 
        view 
        returns (uint256) 
    {
      uint256 stakingFactor_ = FixedPointMathLib.sqrt(
          (amountStaked[tokenId] + stakeAtRisk) / 10**18
      );
      if (stakingFactor_ == 0) {
        stakingFactor_ = 1;
      }
      return stakingFactor_;
    }    
}"},"src/StakeAtRisk.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;

import { Neuron } from "./Neuron.sol";
import { RankedBattle } from "./RankedBattle.sol";

/// @title StakeAtRisk
/// @author ArenaX Labs Inc.
/// @notice Manages the NRNs that are at risk of being lost during a round of competition
contract StakeAtRisk {

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Event emitted when NRNs are reclaimed from this contract (after a win in ranked).
    event ReclaimedStake(uint256 fighterId, uint256 reclaimAmount);

    /// @notice Event emitted when more NRNs are placed at risk.
    event IncreasedStakeAtRisk(uint256 fighterId, uint256 atRiskAmount);

    /*//////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    /// @notice The current roundId.
    uint256 public roundId = 0;    

    /// @notice The treasury address.
    address public treasuryAddress;

    /// @notice The RankedBattle contract address.
    address _rankedBattleAddress;

    /// @notice The Neuron contract instance.
    Neuron _neuronInstance;

    /*//////////////////////////////////////////////////////////////
                                MAPPINGS
    //////////////////////////////////////////////////////////////*/

    /// @notice Maps the roundId to the total stake at risk for that round.
    mapping(uint256 => uint256) public totalStakeAtRisk;

    /// @notice Maps the roundId to the fighterId to the stake at risk for that fighter.
    mapping(uint256 => mapping(uint256 => uint256)) public stakeAtRisk;

    /// @notice Mapping of address to the amount of NRNs that have been swept.
    mapping(address => uint256) public amountLost;

    /*//////////////////////////////////////////////////////////////
                               CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /// @notice Sets the community treasury address and ranked battle contract address.
    /// Instantiates the Neuron contract.
    /// @param treasuryAddress_ The address of the treasury contract
    /// @param nrnAddress The address of the Neuron contract
    /// @param rankedBattleAddress The address of the Ranked Battle contract
    constructor(
        address treasuryAddress_,
        address nrnAddress,
        address rankedBattleAddress
    ) {
        treasuryAddress = treasuryAddress_;
        _rankedBattleAddress = rankedBattleAddress;   
        _neuronInstance = Neuron(nrnAddress);
    }

    /*//////////////////////////////////////////////////////////////
                            EXTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @notice Sets a new round for staking
    /// @dev This function can only be called by the RankedBattle contract to set a new round for staking.
    /// @dev At the end of a round, it sweeps all NRNs held in this contract and sends it to treasury.
    /// @param roundId_ The ID of the new round.
    function setNewRound(uint256 roundId_) external {
        require(msg.sender == _rankedBattleAddress, "Not authorized to set new round");
        bool success = _sweepLostStake();
        if (success) {
            roundId = roundId_;
        }
    }

    /// @notice Reclaims NRN tokens from the stake at risk.
    /// @dev This function can only be called by the RankedBattle contract to reclaim 
    /// NRN tokens from the stake at risk.
    /// @dev This gets triggered when they win a match while having NRNs at risk.
    /// @param nrnToReclaim The amount of NRN tokens to reclaim.
    /// @param fighterId The ID of the fighter.
    /// @param fighterOwner The owner of the fighter.
    function reclaimNRN(uint256 nrnToReclaim, uint256 fighterId, address fighterOwner) external {
        require(msg.sender == _rankedBattleAddress, "Call must be from RankedBattle contract");
        require(
            stakeAtRisk[roundId][fighterId] >= nrnToReclaim, 
            "Fighter does not have enough stake at risk"
        );

        bool success = _neuronInstance.transfer(_rankedBattleAddress, nrnToReclaim);
        if (success) {
            stakeAtRisk[roundId][fighterId] -= nrnToReclaim;
            totalStakeAtRisk[roundId] -= nrnToReclaim;
            amountLost[fighterOwner] -= nrnToReclaim;
            emit ReclaimedStake(fighterId, nrnToReclaim);
        }
    }

    /// @notice Updates the stake at risk records for a fighter.
    /// @dev This function can only be called by the RankedBattle contract to update the stake at 
    /// risk records for a fighter.
    /// @dev This gets triggered when the fighter has 0 points and loses (i.e. goes into deficit).
    /// @param nrnToPlaceAtRisk The amount of NRN tokens to place at risk.
    /// @param fighterId The ID of the fighter.
    function updateAtRiskRecords(
        uint256 nrnToPlaceAtRisk, 
        uint256 fighterId, 
        address fighterOwner
    ) 
        external 
    {
        require(msg.sender == _rankedBattleAddress, "Call must be from RankedBattle contract");
        stakeAtRisk[roundId][fighterId] += nrnToPlaceAtRisk;
        totalStakeAtRisk[roundId] += nrnToPlaceAtRisk;
        amountLost[fighterOwner] += nrnToPlaceAtRisk;
        emit IncreasedStakeAtRisk(fighterId, nrnToPlaceAtRisk);
    }   

    /// @notice Gets the stake at risk for a specific fighter in the current round.
    /// @param fighterId The ID of the fighter.
    /// @return Amount of NRN tokens at risk for the fighter in the current round.
    function getStakeAtRisk(uint256 fighterId) external view returns(uint256) {
        return stakeAtRisk[roundId][fighterId];
    }

    /*//////////////////////////////////////////////////////////////
                            PRIVATE FUNCTIONS
    //////////////////////////////////////////////////////////////*/    

    /// @notice Sweeps the lost stake to the treasury contract.
    /// @dev This function is called internally to transfer the lost stake to the treasury contract.
    function _sweepLostStake() private returns(bool) {
        return _neuronInstance.transfer(treasuryAddress, totalStakeAtRisk[roundId]);
    }
}"},"src/Verification.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;

library Verification {
    // https://ethereum.stackexchange.com/questions/74002/solidity-extract-data-from-signed-message
    function verify(
        bytes32 msgHash, 
        bytes memory signature,
        address signer
    ) 
        public 
        pure 
        returns(bool) 
    {
        require(signature.length == 65, "invalid signature length");

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            /*
            First 32 bytes stores the length of the signature

            add(sig, 32) = pointer of sig + 32
            effectively, skips first 32 bytes of signature

            mload(p) loads next 32 bytes starting at the memory address p into memory
            */

            // first 32 bytes, after the length prefix
            r := mload(add(signature, 32))
            // second 32 bytes
            s := mload(add(signature, 64))
            // final byte (first byte of the next 32 bytes)
            v := byte(0, mload(add(signature, 96)))
        }
        bytes memory prefix = "\x19Ethereum Signed Message:\n32";
        bytes32 prefixedHash = keccak256(abi.encodePacked(prefix, msgHash));
        return ecrecover(prefixedHash, v, r, s) == signer;
    }
}"},"src/VoltageManager.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;

import { GameItems } from "./GameItems.sol";

/// @title VoltageManager 
/// @author ArenaX Labs Inc.
/// @notice Manages the voltage system for AI Arena
contract VoltageManager {

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Event emitted when voltage amount is altered.
    event VoltageRemaining(address spender, uint8 voltage);  

    /*//////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    /// The address that has owner privileges (initially the contract deployer).
    address _ownerAddress;

    /// @dev The game items contract instance.
    GameItems _gameItemsContractInstance;

    /*//////////////////////////////////////////////////////////////
                                MAPPINGS
    //////////////////////////////////////////////////////////////*/

    /// @notice Maps the address to the allowed voltage spenders.
    mapping(address => bool) public allowedVoltageSpenders;

    /// @notice Maps the address to the voltage replenish time.
    mapping(address => uint32) public ownerVoltageReplenishTime;

    /// @notice Maps the address to the voltage.
    mapping(address => uint8) public ownerVoltage;

    /// @notice Mapping of address to admin status.
    mapping(address => bool) public isAdmin;

    /*//////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /// @notice Sets the owner address and instantiates the Game Items contract.
    /// @param ownerAddress The address of the owner.
    /// @param gameItemsContractAddress The address of the game items contract.
    constructor(address ownerAddress, address gameItemsContractAddress) {
        _ownerAddress = ownerAddress;
        _gameItemsContractInstance = GameItems(gameItemsContractAddress);
        isAdmin[_ownerAddress] = true;
    } 

    /*//////////////////////////////////////////////////////////////
                            EXTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @notice Transfers ownership from one address to another.
    /// @dev Only the owner address is authorized to call this function.
    /// @param newOwnerAddress The address of the new owner
    function transferOwnership(address newOwnerAddress) external {
        require(msg.sender == _ownerAddress);
        _ownerAddress = newOwnerAddress;
    }

    /// @notice Adjusts admin access for a user.
    /// @dev Only the owner address is authorized to call this function.
    /// @param adminAddress The address of the admin.
    /// @param access Whether the address has admin access or not.
    function adjustAdminAccess(address adminAddress, bool access) external {
        require(msg.sender == _ownerAddress);
        isAdmin[adminAddress] = access;
    }  

    /// @notice Adjusts whether a given address is allowed to spend voltage
    /// @dev Only admins are authorized to call this function.
    /// @param allowedVoltageSpender The address of the allowed voltage spender.
    /// @param allowed Whether the spender is allowed or not
    function adjustAllowedVoltageSpenders(address allowedVoltageSpender, bool allowed) external {
        require(isAdmin[msg.sender]);
        allowedVoltageSpenders[allowedVoltageSpender] = allowed;
    }

    /*//////////////////////////////////////////////////////////////
                            PUBLIC FUNCTIONS
    //////////////////////////////////////////////////////////////*/    

    /// @notice Uses a voltage battery to replenish voltage for a player in AI Arena.
    /// @dev This function can be called by any user to use the voltage battery.
    function useVoltageBattery() public {
        require(ownerVoltage[msg.sender] < 100);
        require(_gameItemsContractInstance.balanceOf(msg.sender, 0) > 0);
        _gameItemsContractInstance.burn(msg.sender, 0, 1);
        ownerVoltage[msg.sender] = 100;
        emit VoltageRemaining(msg.sender, ownerVoltage[msg.sender]);
    }

    /// @notice Spends voltage.
    /// @dev This function can be called by the user or an allowed voltage spender.
    /// @param spender The address of the spender.
    /// @param voltageSpent The amount of voltage to spend.
    function spendVoltage(address spender, uint8 voltageSpent) public {
        require(spender == msg.sender || allowedVoltageSpenders[msg.sender]);
        if (ownerVoltageReplenishTime[spender] <= block.timestamp) {
            _replenishVoltage(spender);
        }
        ownerVoltage[spender] -= voltageSpent;
        emit VoltageRemaining(spender, ownerVoltage[spender]);
    }

    /// @notice Replenishes voltage and sets the replenish time to 1 day from now
    /// @dev This function is called internally to replenish the voltage for the owner.
    /// @param owner The address of the owner
    function _replenishVoltage(address owner) private {
        ownerVoltage[owner] = 100;
        ownerVoltageReplenishTime[owner] = uint32(block.timestamp + 1 days);
    }    
}
"}}}
